<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($product['name']) ?> · MobileX</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="/public/assets/css/site.css"></head><body class="bg-slate-950 text-slate-100"><main class="mx-auto max-w-6xl p-5 pt-10"><a href="?page=products" class="text-blue-300">← Sản phẩm</a><div class="mt-5 grid gap-8 md:grid-cols-2"><section class="rounded-xl bg-slate-900 p-5"><img id="hero" class="mx-auto max-h-[28rem]" src="<?= $e($product['images'][0]['image_url']??$product['variants'][0]['image_url']??'') ?>" alt="<?= $e($product['images'][0]['alt_text']??$product['name']) ?>"><div class="mt-4 flex gap-2 overflow-auto"><?php foreach($product['images'] as $image): ?><button class="gallery-image rounded border border-slate-700 p-1" data-src="<?= $e($image['image_url']) ?>"><img class="h-16 w-16 object-cover" src="<?= $e($image['image_url']) ?>" alt="<?= $e($image['alt_text']??$product['name']) ?>"></button><?php endforeach ?></div></section><section><p class="text-sm text-blue-300"><?= $e($product['brand']??'') ?> · <?= $e($product['category']??'') ?></p><h1 class="my-2 text-3xl font-bold"><?= $e($product['name']) ?></h1><p class="mb-5 text-slate-300"><?= nl2br($e($product['description']??'')) ?></p>
<form method="post" action="?page=checkout" class="space-y-4 rounded-xl bg-slate-900 p-5"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="action" value="add"><label class="block">Phiên bản<select id="variant" name="product_id" required class="mt-1 w-full rounded bg-slate-800 p-3"><?php foreach($product['variants'] as $v): ?><option value="<?= (int)$v['id'] ?>" data-price="<?= (float)$v['price'] ?>" data-stock="<?= (int)$v['stock'] ?>" data-image="<?= $e($v['image_url']??'') ?>"><?= $e(($v['attributes']?:$v['sku']).' · '.$v['sku']) ?></option><?php endforeach ?></select></label><p class="text-3xl font-bold text-blue-300" id="price"></p><p id="stock" class="text-emerald-300"></p><label>Số lượng<input id="quantity" name="quantity" type="number" min="1" value="1" class="ml-2 w-24 rounded bg-slate-800 p-2"></label><button id="add" class="w-full rounded bg-blue-600 p-3 font-bold">Thêm vào giỏ hàng</button></form></section></div>
<?php if($product['compatible']): ?><section class="mt-8 rounded-xl bg-slate-900 p-5"><h2 class="text-xl font-bold">Sản phẩm tương thích</h2><ul class="mt-3 list-inside list-disc"><?php foreach($product['compatible'] as $c): ?><li><a class="text-blue-300" href="?page=detail&amp;product_id=<?= (int)$c['id'] ?>"><?= $e($c['name']) ?></a> — <?= $e($c['note']??'') ?></li><?php endforeach ?></ul></section><?php endif ?><a class="mt-6 inline-block text-blue-300" href="?page=reviews&amp;product_id=<?= (int)$product['id'] ?>">Đánh giá sản phẩm</a></main><script>
const v=document.querySelector('#variant'),q=document.querySelector('#quantity'),price=document.querySelector('#price'),stock=document.querySelector('#stock'),add=document.querySelector('#add');let latest=0;async function update(){const id=v.value,request=++latest;add.disabled=true;try{const r=await fetch('?page=variant&id='+encodeURIComponent(id));if(!r.ok)throw Error();const data=await r.json();if(request!==latest)return;price.textContent=new Intl.NumberFormat('vi-VN').format(Number(data.price))+' ?';stock.textContent=Number(data.stock)?'C?n h?ng: '+data.stock:'H?t h?ng';q.max=data.stock||1;q.value=Math.min(Math.max(1,Number(q.value)),Number(data.stock)||1);add.disabled=!Number(data.stock);if(data.image_url)document.querySelector('#hero').src=data.image_url}catch{stock.textContent='Kh?ng t?i ???c t?n kho';add.disabled=true}}v.addEventListener('change',update);q.addEventListener('input',()=>{if(Number(q.value)>Number(q.max))q.value=q.max});document.querySelectorAll('.gallery-image').forEach(b=>b.onclick=()=>document.querySelector('#hero').src=b.dataset.src);update();
</script></body></html>
